class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        best = 0
        for left in range(len(s)):
            for right in range(left, len(s)):
                sub = s[left:right + 1]
                if len(set(sub)) == len(sub):
                    best = max(best, len(sub))
        return best

solutions.better:
class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        best = 0
        for left in range(len(s)):
            seen = set()
            for right in range(left, len(s)):
                if s[right] in seen:
                    break
                seen.add(s[right])
                best = max(best, right - left + 1)
        return best

solutions.optimal:
class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        last_seen = {}
        left = 0
        best = 0
        for right, ch in enumerate(s):
            if ch in last_seen and last_seen[ch] >= left:
                left = last_seen[ch] + 1
            last_seen[ch] = right
            best = max(best, right - left + 1)
        return best

